impl<T: gx::Real> Twist<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t4 = x[4] * x[4];
        let t6 = x[0].mul_add(x[0], t1);
        let t7 = x[2].mul_add(x[2], t6);
        let t8 = x[3].mul_add(x[3], t4);
        let t9 = x[5].mul_add(x[5], t8);
        let t10 = t7 - t9;
        t10
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, by Shirokov's method in `Motor` (no closed form
    /// for `Twist` here): the inverse as a polynomial of degree 7 whose coefficients come
    /// from the scalar parts of powers (the FaddeevâLeVerrier recursion on left multiplication,
    /// 7 products in `Motor`), then 1 NewtonâSchulz step(s) (docs/design.md, ADR-037). `x` is scaled to its largest
    /// coefficient first. Not finite where `x` has no inverse.
    #[inline]
    pub fn inverse(self) -> Motor<(), T>
    where
        T: gx::Real,
    {
        T::vectorize(#[inline(always)] move || {
        let mut size = T::zero();
        for c in self.c {
            size = size.max(c.abs());
        }
        let scale = size.recip();
        let mut x = Motor::<(), T>::zero();
        x.c[1] = self.c[0] * scale;
        x.c[2] = self.c[1] * scale;
        x.c[3] = self.c[2] * scale;
        x.c[4] = self.c[3] * scale;
        x.c[5] = self.c[4] * scale;
        x.c[6] = self.c[5] * scale;
        x.c[7] = self.c[6] * scale;
        x.c[8] = self.c[7] * scale;
        x.c[9] = self.c[8] * scale;
        x.c[10] = self.c[9] * scale;
        let a = x;
        // Uâ = a, Câ = (N/k) â¨Uââ©â, Uâââ = a (Uâ â Câ); then aâ»Â¹ = (U_{Nâ1} â C_{Nâ1}) / C_N.
        let mut prev = a;
        let c = a.c[0] * T::from_i64(8);
        prev.c[0] = prev.c[0] - c;
        for k in 2..8i64 {
            let u = a * prev;
            let c = u.c[0] * T::from_ratio(8, k);
            prev = u;
            prev.c[0] = prev.c[0] - c;
        }
        let det = (a * prev).c[0];
        let mut y = prev.gp(det.recip());
        // NewtonâSchulz, y â y (2 â x y), squares the residual: the recursion loses digits as
        // its degree grows (to 10â»â´ at degree 32), and the step(s) restore them.
        for _ in 0..1 {
            let mut t = -(x * y);
            t.c[0] = t.c[0] + T::from_i64(2);
            y = y * t;
        }
        y.gp(scale)
        })
    }

    /// The exponential, a unit versor: `exp(B) = C(BÂ²) + S(BÂ²) B`, with `BÂ² = Î» + Q` and `QÂ² = q` a scalar.
    #[inline]
    #[allow(unused_variables)]
    pub fn exp(self) -> gx::Unit<Motor<(), T>> {
        T::vectorize(#[inline(always)] move || {
        let x = self.c;
        let p0 = x[0] * x[3];
        let p1 = x[1] * x[4];
        let p2 = x[2] * x[5];
        let p4 = x[1] * x[1];
        let p7 = x[4] * x[4];
        let p11 = p0 * p2;
        let p12 = p1 * p1;
        let p15 = x[3].mul_add(x[3], p7);
        let p16 = x[5].mul_add(x[5], p15);
        let p17 = x[0].mul_add(x[0], p4);
        let p18 = x[2].mul_add(x[2], p17);
        let p19 = p16 - p18;
        let p20 = p0.mul_add(p0, p12);
        let p21 = p2.mul_add(p2, p20);
        let p23 = p0.mul_add(p1, p11);
        let p24 = p1.mul_add(p2, p23);
        let p25 = p24 * T::from_i64(8);
        let p26 = p21.mul_add(T::from_i64(4), p25);
        let p27 = -p26;
        let [c0, c1, s0, s1] = gx::study::exp_coeffs_q(p19, p27);
        let t0 = x[0] * x[3];
        let t2 = x[1] * x[4];
        let t3 = s1 * t2;
        let t4 = x[2] * x[5];
        let t6 = s1.mul_add(t0, t3);
        let t7 = s1.mul_add(t4, t6);
        let t8 = x[0] * x[6];
        let t10 = x[1] * x[7];
        let t11 = s1 * t10;
        let t12 = x[2] * x[8];
        let t14 = s1.mul_add(t8, t11);
        let t15 = s1.mul_add(t12, t14);
        let t16 = x[0] * x[9];
        let t18 = x[4] * x[8];
        let t19 = s1 * t18;
        let t20 = x[5] * x[7];
        let t22 = s1.mul_add(t16, t19);
        let t23 = (-s1).mul_add(t20, t22);
        let t24 = x[1] * x[9];
        let t26 = x[3] * x[8];
        let t28 = x[5] * x[6];
        let t29 = s1 * t28;
        let t30 = s1.mul_add(t24, t29);
        let t31 = (-s1).mul_add(t26, t30);
        let t32 = x[2] * x[9];
        let t34 = x[3] * x[7];
        let t35 = s1 * t34;
        let t36 = x[4] * x[6];
        let t38 = s1.mul_add(t32, t35);
        let t39 = (-s1).mul_add(t36, t38);
        let t40 = x[0] * c1;
        let t41 = x[1] * c1;
        let t42 = x[2] * c1;
        let t43 = x[3] * c1;
        let t44 = x[4] * c1;
        let t45 = x[5] * c1;
        let t47 = x[3] * t7;
        let t49 = x[4] * t7;
        let t51 = x[5] * t7;
        let t52 = x[0] * t7;
        let t53 = x[3] * s0;
        let t54 = x[1] * t7;
        let t55 = x[4] * s0;
        let t56 = x[2] * t7;
        let t57 = x[5] * s0;
        let t60 = x[5] * t31;
        let t63 = x[3] * t39;
        let t68 = x[4] * t23;
        let t71 = x[1] * t31;
        let t73 = x[9] * s0;
        let t75 = x[8] * t44;
        let t79 = x[6] * t45;
        let t81 = x[7] * t43;
        let t84 = x[7] * t41;
        let t87 = x[4] * t41;
        let t89 = t47 * T::from_i64(2);
        let t90 = x[0].mul_add(s0, t89);
        let t91 = t49 * T::from_i64(2);
        let t92 = x[1].mul_add(s0, t91);
        let t93 = t51 * T::from_i64(2);
        let t94 = x[2].mul_add(s0, t93);
        let t96 = (-t52).mul_add(T::from_i64(2), t53);
        let t98 = (-t54).mul_add(T::from_i64(2), t55);
        let t100 = (-t56).mul_add(T::from_i64(2), t57);
        let t101 = (-x[0]).mul_add(t15, t60);
        let t102 = (-x[4]).mul_add(t39, t101);
        let t103 = t102 * T::from_i64(2);
        let t104 = x[6].mul_add(s0, t103);
        let t105 = (-x[1]).mul_add(t15, t63);
        let t106 = (-x[5]).mul_add(t23, t105);
        let t107 = t106 * T::from_i64(2);
        let t108 = x[7].mul_add(s0, t107);
        let t109 = (-x[2]).mul_add(t15, t68);
        let t110 = (-x[3]).mul_add(t31, t109);
        let t111 = t110 * T::from_i64(2);
        let t112 = x[8].mul_add(s0, t111);
        let t113 = x[0].mul_add(t23, t71);
        let t114 = x[2].mul_add(t39, t113);
        let t116 = (-t114).mul_add(T::from_i64(2), t73);
        let t117 = x[9].mul_add(t40, t75);
        let t118 = (-x[7]).mul_add(t45, t117);
        let t119 = t118 * T::from_i64(2);
        let t120 = x[9].mul_add(t41, t79);
        let t121 = (-x[8]).mul_add(t43, t120);
        let t122 = t121 * T::from_i64(2);
        let t123 = x[9].mul_add(t42, t81);
        let t124 = (-x[6]).mul_add(t44, t123);
        let t125 = t124 * T::from_i64(2);
        let t126 = x[6].mul_add(t40, t84);
        let t127 = x[8].mul_add(t42, t126);
        let t128 = t127 * T::from_i64(2);
        let t129 = x[3].mul_add(t40, t87);
        let t130 = x[5].mul_add(t42, t129);
        let t131 = t130 * T::from_i64(2);
        let t132 = -t131;
        gx::Unit::new_unchecked(Motor::from_coeffs([c0, t90, t92, t94, t96, t98, t100, t104, t108, t112, t116, t119, t122, t125, t128, t132]))
        })
    }

}

