impl<S1: gx::Slots, S2: gx::Slots, T: gx::Coef> gx::Gp<Scalar<S2, T>> for Quadvector<S1, T> {
    type Output = Quadvector<gx::Cat<S1, S2>, T>;
    #[inline(always)]
    fn gp(self, rhs: Scalar<S2, T>) -> Quadvector<gx::Cat<S1, S2>, T> {
        let a = self.c.map(gx::SlotArr::<S1, T>);
        let b = rhs.c.map(gx::SlotArr::<S2, T>);
        let p = move |i: usize, j: usize| a[i] * b[j];
        Quadvector {
            c: [
                (p(0, 0)).0,
                (p(1, 0)).0,
                (p(2, 0)).0,
                (p(3, 0)).0,
                (p(4, 0)).0,
                (p(5, 0)).0,
                (p(6, 0)).0,
                (p(7, 0)).0,
                (p(8, 0)).0,
                (p(9, 0)).0,
                (p(10, 0)).0,
                (p(11, 0)).0,
                (p(12, 0)).0,
                (p(13, 0)).0,
                (p(14, 0)).0,
            ],
        }
    }
}

