impl<S: gx::Slots, T: gx::Real> gx::DivBy<Scalar<(), T>> for Scalar<S, T> {
    type Output = <Self as gx::Gp<Scalar<(), T>>>::Output;
    #[inline(always)]
    fn div_by(self, rhs: Scalar<(), T>) -> Self::Output {
        gx::Gp::gp(self, rhs.inverse())
    }
}

