impl<S: gx::Slots, T: gx::Coef> gx::Transform<Pseudoscalar<S, T>> for Vector<(), T> {
    type Output = Pseudoscalar<S, T>;
    #[inline(always)]
    fn transform(self, x: Pseudoscalar<S, T>) -> Pseudoscalar<S, T> {
        let v = self.c;
        if let Some(xv) = gx::slots::values::<S, T, 1>(&x.c) {
        let t1 = v[1] * v[1];
        let t2 = v[2] * v[2];
        let t4 = v[4] * v[5];
        let t5 = v[0].mul_add(v[0], t1);
        let t6 = (-v[3]).mul_add(v[3], t2);
        let t7 = t5 + t6;
        let t9 = (-t4).mul_add(T::from_i64(2), t7);
        let t10 = xv[0] * t9;
        let t11 = -t10;
            return Pseudoscalar { c: gx::slots::from_values::<S, T, 1>([t11]) };
        }
        let m2 = v[2] * v[2];
        let m3 = v[3] * v[3];
        let m4 = v[4] * v[5];
        let m5 = (-v[0]).mul_add(v[0], m3);
        let m6 = v[1].mul_add(v[1], m2);
        let m7 = m5 - m6;
        let m9 = m4.mul_add(T::from_i64(2), m7);
        let x = x.c.map(gx::SlotArr::<S, T>);
        Pseudoscalar { c: [(x[0].scale(m9)).0] }
    }
}

