impl gx::batch::SandwichKernel<Motor, gx::batch::Certified> for Vector {
    type Y = Even;
    type Versor<T: gx::Coef> = gx::Unit<Vector<(), T>>;
    type Prepared<T: gx::Coef> = gx::Prepared<gx::Unit<Vector>, Motor, T, 45>;
    #[inline(always)]
    fn wrap<T: gx::Coef>(v: Vector<(), T>) -> gx::Unit<Vector<(), T>> {
        gx::Unit::new_unchecked(v)
    }
    #[inline(always)]
    fn unwrap<T: gx::Coef>(v: gx::Unit<Vector<(), T>>) -> Vector<(), T> {
        v.into_inner()
    }
    #[inline(always)]
    fn prepare<T: gx::Coef>(v: gx::Unit<Vector<(), T>>) -> gx::Prepared<gx::Unit<Vector>, Motor, T, 45> {
        gx::Prepare::<Motor>::prepare(v)
    }
    #[inline(always)]
    fn map_prepared<T: gx::Coef, W: gx::Coef>(p: gx::Prepared<gx::Unit<Vector>, Motor, T, 45>, mut f: impl FnMut(T) -> W) -> gx::Prepared<gx::Unit<Vector>, Motor, W, 45> {
        let m = p.m;
        gx::Prepared::from_entries([f(m[0]), f(m[1]), f(m[2]), f(m[3]), f(m[4]), f(m[5]), f(m[6]), f(m[7]), f(m[8]), f(m[9]), f(m[10]), f(m[11]), f(m[12]), f(m[13]), f(m[14]), f(m[15]), f(m[16]), f(m[17]), f(m[18]), f(m[19]), f(m[20]), f(m[21]), f(m[22]), f(m[23]), f(m[24]), f(m[25]), f(m[26]), f(m[27]), f(m[28]), f(m[29]), f(m[30]), f(m[31]), f(m[32]), f(m[33]), f(m[34]), f(m[35]), f(m[36]), f(m[37]), f(m[38]), f(m[39]), f(m[40]), f(m[41]), f(m[42]), f(m[43]), f(m[44])])
    }
    #[inline(always)]
    fn apply_prepared<T: gx::Coef>(p: gx::Prepared<gx::Unit<Vector>, Motor, T, 45>, x: Motor<(), T>) -> Even<(), T> {
        gx::Transform::transform(p, x)
    }
    #[inline(always)]
    fn apply<T: gx::Coef>(v: gx::Unit<Vector<(), T>>, x: Motor<(), T>) -> Even<(), T> {
        gx::Transform::transform(v, x)
    }
}

