    #[inline(always)]
    fn apply_prepared<T: gx::Coef>(p: gx::Prepared<gx::Unit<Motor>, Quintvector, T, 31>, x: Quintvector<(), T>) -> Odd<(), T> {
        gx::Transform::transform(p, x)
    }
    #[inline(always)]
