#[cfg(feature = "bytemuck")]
/// Alias of [`VectorGpu`].
pub type EventGpu = VectorGpu;

#[cfg(feature = "bytemuck")]
/// Alias of [`VectorGpu16`].
pub type EventGpu16 = VectorGpu16;

